using Godot;
using System;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class StructureBridgeOperations:RefCounted
{
    private readonly ActorAnimationOperations _animation=new();private readonly PhysicsSettingsOperations _settings=new();private readonly ModelMeshOperations _meshes=new();private readonly PhysicsCollisionWorldOperations _collision=new();private readonly DestructionMaterialOperations _materials=new();private readonly ActorDataOperations _data=new();private static Settings Map(GodotObject owner,string key)=>owner.Get(key).AsGodotDictionary();private static GArray Edges(RefCounted owner)=>owner.Get("edges").AsGodotArray();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;private static Resource Actor(RefCounted controller,string id)=>Map(controller,"prototypes")[id].AsGodotDictionary()["actor"].As<Resource>();private Settings Values(RefCounted controller,string id,double time){var actor=Actor(controller,id);return _animation.sampled_values(actor,controller.Call("_local",actor,time).AsDouble());}
    public void reset(RefCounted owner){foreach(string key in new[]{"nodes","islands","excluded"})Map(owner,key).Clear();Edges(owner).Clear();owner.Set("graph_key",0);owner.Set("enabled",false);owner.Set("excluded_time",double.NaN);}
    public GArray exclusions(RefCounted owner,RefCounted controller,string id,double time){var excluded=Map(owner,"excluded");double cached=owner.Get("excluded_time").AsDouble();if(!double.IsNaN(cached)&&Mathf.IsEqualApprox(cached,time))return Get(excluded,id,new GArray()).AsGodotArray().Duplicate();owner.Set("excluded_time",time);excluded.Clear();foreach(var source in Map(controller,"prototypes").Keys){string sourceId=source.AsString();var values=Values(controller,sourceId,time);if(!Get(values,"structure_enabled",false).AsBool())continue;var saved=Get(Get(Map(controller,"states")[source].AsGodotDictionary(),"structural",new Settings()).AsGodotDictionary(),"links",new Settings()).AsGodotDictionary();foreach(var entry in Get(values,"structure_connections",new Settings()).AsGodotDictionary()){var link=entry.Value.AsGodotDictionary();string target=Get(link,"target","").AsString();var history=Get(saved,entry.Key.AsString(),new Settings()).AsGodotDictionary();if(!Get(link,"exclude_collision",true).AsBool()||!Get(link,"enabled",true).AsBool()||Get(history,"broken",false).AsBool())continue;if(!excluded.ContainsKey(source))excluded[source]=new GArray();if(!excluded.ContainsKey(target))excluded[target]=new GArray();excluded[source].AsGodotArray().Add(target);excluded[target].AsGodotArray().Add(source);}}return Get(excluded,id,new GArray()).AsGodotArray().Duplicate();}
    public void add_node(RefCounted owner,RefCounted controller,string id,string actorId,Settings state,Settings config,int role,Aabb bounds,double mass,bool locked){var nodes=Map(owner,"nodes");if(nodes.Count>=512){controller.Call("_warn","Structure: 512-element limit reached; split or simplify the assembly.");return;}var size=bounds.Size*state["pose"].AsTransform3D().Basis.Scale.Abs();double inverse=role!=0||locked?0:1/Math.Max(.001,mass);nodes[id]=new Settings{["id"]=id,["owner"]=actorId,["state"]=state,["mass"]=mass,["inv"]=inverse,["inertia"]=inverse*12/Math.Max(.001,size.LengthSquared()),["config"]=config,["bounds"]=bounds,["fixed"]=role!=0||locked,["before"]=state["pose"],["contact"]=false};}
    public Settings endpoint(RefCounted owner,string actorId,Vector3 local){var nodes=Map(owner,"nodes");if(nodes.ContainsKey(actorId))return new Settings{["id"]=actorId,["local"]=local};var best=new Settings();double score=double.PositiveInfinity;foreach(var entry in nodes){var node=entry.Value.AsGodotDictionary();if(node["owner"].AsString()!=actorId)continue;var state=node["state"].AsGodotDictionary();var point=local-Get(state,"structure_origin",Vector3.Zero).AsVector3();var bounds=node["bounds"].AsAabb();double distance=point.DistanceSquaredTo(point.Clamp(bounds.Position,bounds.End));if(distance<.0001){var mesh=new ModelMeshOperations.Snapshot(state["mesh"].As<Resource>());for(int face=0;face<mesh.Faces.Length;face++)if(mesh.Normal(face).Dot(point-mesh.Center(face))>.01){distance=double.PositiveInfinity;break;}}if(distance<score&&distance<.0001){score=distance;best=new Settings{["id"]=entry.Key,["local"]=point};}}return best;}
    public void rotate(Settings node,Vector3 delta){if(delta.LengthSquared()<1e-16)return;float length=Math.Min(.25f,delta.Length());var state=node["state"].AsGodotDictionary();var pose=state["pose"].AsTransform3D();pose.Basis=new Basis(new Quaternion(delta.Normalized(),length))*pose.Basis;state["pose"]=pose;}
    public void solve(RefCounted owner,Settings edge,double dt)
    {
        var saved=edge["saved"].AsGodotDictionary();if(saved["broken"].AsBool())return;var nodes=Map(owner,"nodes");var endpointA=edge["a"].AsGodotDictionary();var endpointB=edge["b"].AsGodotDictionary();var a=nodes[endpointA["id"]].AsGodotDictionary();var b=nodes[endpointB["id"]].AsGodotDictionary();var link=edge["link"].AsGodotDictionary();int kind=Get(link,"type",0).AsInt32();var stateA=a["state"].AsGodotDictionary();var stateB=b["state"].AsGodotDictionary();var poseA=stateA["pose"].AsTransform3D();var poseB=stateB["pose"].AsTransform3D();var ra=poseA.Basis*endpointA["local"].AsVector3();var rb=poseB.Basis*endpointB["local"].AsVector3();var difference=poseA.Origin+ra-poseB.Origin-rb;var frame=poseB.Basis.Orthonormalized()*Basis.FromEuler(Get(link,"orientation",Vector3.Zero).AsVector3()*(Mathf.Pi/180));var axis=frame.Y.Normalized();var constrained=difference;if(kind==2){float limit=Get(link,"limit",1).AsSingle();constrained-=axis*Math.Clamp(difference.Dot(axis),-limit,limit);}if(kind is 3 or 4){double length=Get(link,"length",0).AsDouble();constrained=difference.Normalized()*(float)(difference.Length()-length);if(kind==3&&Get(link,"tension_only",true).AsBool()&&difference.Length()<=length)constrained=Vector3.Zero;}double alpha=1/Math.Max(.01,Get(link,"stiffness",100000).AsDouble())/dt/dt;for(int i=0;i<3;i++){var n=Vector3.Zero;n[i]=1;var ga=ra.Cross(n);var gb=rb.Cross(n);double denominator=a["inv"].AsDouble()+b["inv"].AsDouble()+a["inertia"].AsDouble()*ga.LengthSquared()+b["inertia"].AsDouble()*gb.LengthSquared()+alpha;if(denominator<=0)continue;var linear=edge["linear"].AsVector3();double correction=(-constrained[i]-alpha*linear[i])/denominator;linear[i]=(float)(linear[i]+correction);edge["linear"]=linear;poseA=stateA["pose"].AsTransform3D();poseB=stateB["pose"].AsTransform3D();poseA.Origin+=n*(float)(correction*a["inv"].AsDouble());poseB.Origin-=n*(float)(correction*b["inv"].AsDouble());stateA["pose"]=poseA;stateB["pose"]=poseB;rotate(a,ga*(float)(correction*a["inertia"].AsDouble()));rotate(b,-gb*(float)(correction*b["inertia"].AsDouble()));}if(kind is 0 or 1 or 2){var qa=stateA["pose"].AsTransform3D().Basis.Orthonormalized().GetRotationQuaternion();var qb=stateB["pose"].AsTransform3D().Basis.Orthonormalized().GetRotationQuaternion();var error=qa*(qb*saved["rest"].AsBasis().GetRotationQuaternion()).Inverse();double angle=Mathf.Wrap(error.GetAngle(),-Mathf.Pi,Mathf.Pi);var vector=Math.Abs(angle)>1e-8?error.GetAxis()*(float)angle:Vector3.Zero;if(kind==1)vector-=axis*vector.Dot(axis);double compliance=1/Math.Max(.01,Get(link,"angular_stiffness",100000).AsDouble())/dt/dt,denominator=a["inertia"].AsDouble()+b["inertia"].AsDouble()+compliance;if(denominator>0){var angular=edge["angular"].AsVector3();var correction=(-vector-angular*(float)compliance)/(float)denominator;edge["angular"]=angular+correction;rotate(a,correction*a["inertia"].AsSingle());rotate(b,-correction*b["inertia"].AsSingle());}}
    }
